package com.aoo.bcg.common.repair;import com.aoo.bcg.common.config.RoomRuleSnapshot;import java.time.Instant;import java.util.*;
/** Repairs configuration by publishing a superseding snapshot; historical rows are never updated. */
public final class ImmutableConfigSnapshotRepair{public record Supersession(long originalConfigId,RoomRuleSnapshot replacement,String reason){public Supersession{if(originalConfigId<=0||replacement==null||reason==null||reason.isBlank())throw new IllegalArgumentException("invalid snapshot supersession");}}public interface AppendOnlyStore{Optional<RoomRuleSnapshot>find(long configId);void append(Supersession supersession);}public RoomRuleSnapshot publish(AppendOnlyStore store,long originalId,long newConfigId,String newPlayVersion,Instant publishedAt,Map<String,Object> correctedRules,String reason){Objects.requireNonNull(store);RoomRuleSnapshot old=store.find(originalId).orElseThrow(()->new IllegalArgumentException("historical snapshot missing"));if(newConfigId==originalId||newConfigId<=0||newPlayVersion==null||newPlayVersion.equals(old.playVersion())||publishedAt==null||!publishedAt.isAfter(old.publishedAt()))throw new IllegalArgumentException("replacement must have new identity, version and later publication time");RoomRuleSnapshot replacement=new RoomRuleSnapshot(newConfigId,old.gameId(),newPlayVersion,old.componentVersion(),old.roomProfileVersion(),old.flowVersion(),old.scoreVersion(),old.uiProfileVersion(),publishedAt,correctedRules);store.append(new Supersession(originalId,replacement,reason));return replacement;}}
